import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if webpage_url.startswith("http://") or webpage_url.startswith("https://"):
        try:
            response = requests.get(webpage_url, timeout=10)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(f"Error fetching URL content: {e}") from e
    else:
        try:
            with open(webpage_url, "r", encoding="utf-8") as f:
                content = f.read()
        except OSError as e:
            raise requests.RequestException(f"Error reading local HTML file: {e}") from e

    try:
        tree = html.fromstring(content)
        tables = tree.xpath("//table")
        if not tables:
            return 0
        table_html = html.tostring(tables[0], encoding="unicode")
        dfs = pd.read_html(table_html)
        if not dfs:
            return 0
        df = dfs[0]
        if df.empty:
            return 0
    except Exception:
        return 0

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        row_count = len(df)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}") from e

    return row_count

